import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Étiquettes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/concepts/tags.md","filePath":"fr/concepts/tags.md","lastUpdated":1784903584000}'),n={name:"fr/concepts/tags.md"};function l(p,s,o,r,d,u){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="etiquettes" tabindex="-1">Étiquettes <a class="header-anchor" href="#etiquettes" aria-label="Permalink to &quot;Étiquettes&quot;">​</a></h1><p>Une étiquette (tag) est une catégorie qui regroupe des points d&#39;accès connexes au sein d&#39;une collection. Les étiquettes peuvent exister ou non — toutes les collections n&#39;en ont pas, et une collection peut avoir n&#39;importe quel nombre d&#39;étiquettes.</p><p>Les étiquettes proviennent du fichier OpenAPI/Swagger/Postman lui-même. Il n&#39;y a <strong>aucun paramètre de configuration YAML</strong> pour les étiquettes — vous ne pouvez pas créer, renommer ou supprimer des étiquettes dans <code>swag2mcp.yaml</code>. La seule façon de modifier les étiquettes est de modifier le fichier de spécification original.</p><h2 id="hierarchie" tabindex="-1">Hiérarchie <a class="header-anchor" href="#hierarchie" aria-label="Permalink to &quot;Hiérarchie&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domaine, par ex. « meteo »)</span></span>
<span class="line"><span>  └── Collection (fichier de spec, par ex. forecast.yml)</span></span>
<span class="line"><span>        └── Étiquette « meteo »</span></span>
<span class="line"><span>              └── GET /forecast</span></span>
<span class="line"><span>              └── GET /forecast/hourly</span></span>
<span class="line"><span>        └── Étiquette « alertes »</span></span>
<span class="line"><span>              └── GET /alerts</span></span></code></pre></div><h2 id="comment-les-etiquettes-sont-creees" tabindex="-1">Comment les étiquettes sont créées <a class="header-anchor" href="#comment-les-etiquettes-sont-creees" aria-label="Permalink to &quot;Comment les étiquettes sont créées&quot;">​</a></h2><p>Les étiquettes sont extraites du document de spécification lors de l&#39;analyse :</p><p><strong>OpenAPI 3.x / Swagger 2.0</strong> — la liste <code>tags</code> de chaque opération devient des étiquettes :</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /animal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;animaux&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Trouver un animal par ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;animaux&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ajouter un nouvel animal&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /animal/{animalId}/uploadImage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;images_animal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Télécharge une image&quot;</span></span></code></pre></div><p><strong>Postman</strong> — chaque dossier de premier niveau devient une étiquette. Les dossiers imbriqués utilisent le nom du dernier dossier.</p><p>Si un point d&#39;accès n&#39;a pas d&#39;étiquette, il est placé sous une étiquette <code>&quot;default&quot;</code>.</p><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Les étiquettes aident le LLM à trouver des groupes de points d&#39;accès connexes. Au lieu de rechercher dans tous les points d&#39;accès d&#39;une collection, le LLM peut d&#39;abord trouver la bonne étiquette, puis lister uniquement les points d&#39;accès qu&#39;elle contient.</p><h2 id="outils-mcp-pour-les-etiquettes" tabindex="-1">Outils MCP pour les étiquettes <a class="header-anchor" href="#outils-mcp-pour-les-etiquettes" aria-label="Permalink to &quot;Outils MCP pour les étiquettes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_by_spec</code></td><td>Toutes les étiquettes dans une spec entière</td></tr><tr><td><code>tag_by_collection</code></td><td>Étiquettes dans une collection spécifique</td></tr><tr><td><code>tag_by_id</code></td><td>Détails de l&#39;étiquette (titre, nombre de méthodes)</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Points d&#39;accès regroupés sous une étiquette</td></tr></tbody></table><h2 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Requête : &quot;Afficher toutes les étiquettes dans la collection animaux&quot;</span></span>
<span class="line"><span>→ tag_by_collection(collectionId: &quot;...&quot;)</span></span>
<span class="line"><span>→ Résultat : animaux (5 méthodes), images_animal (1 méthode)</span></span></code></pre></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Les étiquettes sont en lecture seule du point de vue de la configuration. Pour ajouter, renommer ou supprimer des étiquettes, modifiez le fichier OpenAPI/Swagger/Postman original et exécutez <code>swag2mcp update</code>.</li><li>Les étiquettes ne peuvent pas être filtrées ou désactivées par collection dans la configuration YAML.</li></ul>`,19)])])}const k=e(n,[["render",l]]);export{c as __pageData,k as default};
